contents.rollMessage:
%{
/*******************************************************
 * Add World Items to Current Actor (if missing)
 * - Searches ONLY world items (game.items), not compendia
 * - Adds to selected token actor OR currently open actor sheet
 * Tested approach for Foundry V10/V11 style APIs.
 *******************************************************/

const CONFIG = {
  // === OPTION A: match by exact name (case-insensitive) ===
  itemNames: [
    "Cryptography",
    "Disguise",
    "Escape Artist",
    "Medicine",
    "Research",
    "Rope Use",
    "Sneak",
    "Survival",
    "Bribery",
    "Deception",
    "Etiquette",
    "Interrogation",
    "Negotiation",
    "Animal Handling",
    "Climbing",
    "Detection",
    "Driving",
    "Gambling",
    "Intimidation",
    "Jumping",
    "Lore",
    "Riding",
    "Swimming"
  ],

  // === OPTION B: match by predicate (more flexible) ===
  // If you set this, it will be used IN ADDITION to itemNames
  // Example: (i) => i.type === "skill" && i.name.includes("Storm")
  itemFilter: null,

  // How to decide if the actor already has the item:
  // - "name+type" is usually safest across systems.
  // - "name" only can be ok if your system guarantees unique names.
  existingCheck: "name+type", // "name+type" | "name"

  // If true: prints debug info to console
  debug: false,
};

// -------------------- helper: get current actor --------------------
function getCurrentActor() {
  const tokenActor = canvas?.tokens?.controlled?.[0]?.actor;
  if (tokenActor) return tokenActor;

  // Try: the top-most open actor sheet window
  const openActorApps = Object.values(ui.windows).filter(w => w?.actor);
  if (openActorApps.length) {
    // Heuristic: last opened window is often last in the array
    return openActorApps[openActorApps.length - 1].actor;
  }
  return null;
}

// -------------------- helper: normalize --------------------
const norm = (s) => (s ?? "").toString().trim().toLowerCase();

// -------------------- main --------------------
(async () => {
  //debugger;
  const actor = entity;
  if (!actor) {
    ui.notifications.warn("No actor found. Select a token or open an actor sheet first.");
    return;
  }

  // Build wanted items list from world items only
  const worldItems = Array.from(game.items ?? []);
  if (!worldItems.length) {
    ui.notifications.warn("No World Items found in this world (game.items is empty).");
    return;
  }

  const wantedNames = new Set(CONFIG.itemNames.map(norm).filter(Boolean));

  const matches = worldItems.filter(i => {
    const byName =
      wantedNames.size === 0 ? false : wantedNames.has(norm(i.name));

    const byFilter =
      typeof CONFIG.itemFilter === "function" ? !!CONFIG.itemFilter(i) : false;

    return byName || byFilter;
  });

  if (CONFIG.debug) {
    console.log("[AddWorldItems] Actor:", actor);
    console.log("[AddWorldItems] World items:", worldItems);
    console.log("[AddWorldItems] Matches:", matches);
  }

  if (!matches.length) {
    ui.notifications.info("No matching items found in World Items (game.items).");
    return;
  }

  // Check which ones already exist on actor
  const actorItems = Array.from(actor.items ?? []);
  const hasItem = (candidate) => {
    if (CONFIG.existingCheck === "name") {
      return actorItems.some(ai => norm(ai.name) === norm(candidate.name));
    }
    // default "name+type"
    return actorItems.some(ai =>
      norm(ai.name) === norm(candidate.name) && (ai.type === candidate.type)
    );
  };

  const toAdd = matches.filter(i => !hasItem(i));

  if (!toAdd.length) {
    ui.notifications.info(`All ${matches.length} matching item(s) are already on ${actor.name}.`);
    return;
  }

  // Duplicate to plain objects and create embedded items on actor
  const createData = toAdd.map(i => i.toObject());

  // NOTE: This copies the world item data into the actor.
  // It does NOT create a live link to the world item.
  await actor.createEmbeddedDocuments("Item", createData);

  ui.notifications.info(
    `Added ${toAdd.length} item(s) to ${actor.name}: ${toAdd.map(i => i.name).join(", ")}`
  );
})();
}%
